test("factory", async () => {
  const port = await getFreePort();
  const client = createClient(`http://localhost:${port}/sql`, { schema });

  const shutdown = await start({
    cliOptions: {
      ...cliOptions,
      command: "start",
      port,
      version: "0.0.0",
    },
  });

  const { address } = await deployFactory({ sender: ALICE });
  const { address: pair } = await createPair({
    factory: address,
    sender: ALICE,
  });
  await swapPair({
    pair,
    amount0Out: 1n,
    amount1Out: 1n,
    to: ALICE,
    sender: ALICE,
  });

  await waitForIndexedBlock({
    port,
    chainName: "mainnet",
    block: { number: 3 },
  });

  let result = await client.db.select().from(schema.swapEvent);

  expect(result).toHaveLength(1);
  expect(result[0]).toMatchObject({
    id: expect.any(String),
    from: ALICE.toLowerCase(),
    to: ALICE.toLowerCase(),
    pair,
  });

  await swapPair({
    pair,
    amount0Out: 1n,
    amount1Out: 1n,
    to: ALICE,
    sender: ALICE,
  });

  await waitForIndexedBlock({
    port,
    chainName: "mainnet",
    block: { number: 4 },
  });

  result = await client.db.select().from(schema.swapEvent);

  expect(result).toHaveLength(2);

  await shutdown!();
}, 15_000)

