test("camelCase", async () => {
  const accountCC = onchainTable("accountCc", (p) => ({
    address: p.hex("addressCc").primaryKey(),
    balance: p.bigint(),
  }));

  const accountViewCC = onchainView("accountViewCc").as((qb) =>
    qb.select().from(accountCC),
