  const { database } = await setupDatabaseServices();

  const schema = {
    account: onchainTable("account", (p) => ({
      address: p.hex().primaryKey(),
      balance: p.bigint().notNull(),
    })),
  };

  const indexingCache = createIndexingCache({
    common: context.common,
    schemaBuild: { schema },
    crashRecoveryCheckpoint: undefined,
    eventCount: {},
  });

  const indexingStore = createIndexingStore({
    common: context.common,
    schemaBuild: { schema },
    indexingCache,
    indexingErrorHandler,
  });

  await database.userQB.transaction(async (tx) => {
    indexingCache.qb = tx;
    indexingStore.qb = tx;

    // setup

    await indexingStore.db
      .insert(schema.account)
      .values({ address: zeroAddress, balance: 10n });

    // no function

    let result: any = await indexingStore.db
      .update(schema.account, { address: zeroAddress })
      .set({ balance: 12n });

    expect(result).toMatchObject({
      address: "0x0000000000000000000000000000000000000000",
      balance: 12n,
    });

    result = await indexingStore.db.find(schema.account, {
      address: zeroAddress,
    });

    expect(result).toMatchObject({
      address: "0x0000000000000000000000000000000000000000",
      balance: 12n,
    });

    // function

    result = await indexingStore.db
      .update(schema.account, { address: zeroAddress })
      .set((row) => ({ balance: row.balance + 10n }));

    expect(result).toMatchObject({
      address: "0x0000000000000000000000000000000000000000",
      balance: 22n,
    });

    result = await indexingStore.db.find(schema.account, {
      address: zeroAddress,
    });

    expect(result).toMatchObject({
      address: "0x0000000000000000000000000000000000000000",
      balance: 22n,
    });

    // undefined

    result = await indexingStore.db
      .update(schema.account, { address: zeroAddress })
      .set({ balance: undefined });

    expect(result).toMatchObject({
      address: "0x0000000000000000000000000000000000000000",
      balance: 22n,
    });

    result = await indexingStore.db.find(schema.account, {
      address: zeroAddress,
    });

    expect(result).toMatchObject({
      address: "0x0000000000000000000000000000000000000000",
      balance: 22n,
    });
  });
})

