  const responses = await eth_getTransactionReceipts(fallbackRpc, params);
  expect(
    responses.flatMap(({ receipts }) =>
      receipts.map(({ transactionIndex }) => transactionIndex),
    ),
  ).toStrictEqual(["0x0", "0x1"]);
})

