  };

  const intervals = await syncStore.getIntervals({
    filters: [filterV2],
  });

  const filterIntervals = intervals
    .get(filterV2)!
    .flatMap(({ intervals }) => intervals);
  const factoryIntervals = intervals
    .get(factoryV2)!
    .flatMap(({ intervals }) => intervals);

  expect(filterIntervals).toEqual([]);
