test("copyOnWrite", () => {
  const obj = { a: 1, b: 2 };
  const copiedObj = copyOnWrite(obj);

  expect(obj.a).toBe(1);
  expect(obj.b).toBe(2);

  expect(copiedObj.a).toBe(1);
  expect(copiedObj.b).toBe(2);

  copiedObj.a = 3;

  expect(obj.a).toBe(1);
  expect(obj.b).toBe(2);

  expect(copiedObj.a).toBe(3);
  expect(copiedObj.b).toBe(2);

